"""Spawn and verify the Native walker used for officer-control comparisons."""

from contextlib import contextmanager
import math


def _distance(a, b):
    return math.sqrt((a.x - b.x) ** 2 + (a.y - b.y) ** 2 +
                     (a.z - b.z) ** 2)


@contextmanager
def spawn(world, blueprint, transform, junction_center):
    intended = transform.location
    distance = _distance(intended, junction_center)
    if not math.isfinite(distance) or not 2.0 <= distance <= 20.0:
        raise ValueError('Officer performer outside authored junction band')
    actor = world.try_spawn_actor(blueprint, transform)
    if actor is None:
        raise ValueError('Native officer performer spawn failed')
    try:
        realized = actor.get_location()
        if _distance(realized, intended) > 1.0:
            raise ValueError('Native officer location differs from construction')
        yield actor
    finally:
        actor.destroy()

"""Synchronized original four-camera Native source adapter for officer cases."""

from pathlib import Path
from queue import Empty, Queue

from four_camera import CAMERAS, FourCameraEncoder


class CameraMedia:
    def __init__(self, world, root, blueprints, mounts, actors, *, timeout_s=10,
                 encoder_factory=FourCameraEncoder):
        if set(blueprints) != set(CAMERAS) or set(mounts) != set(CAMERAS):
            raise ValueError('Four camera blueprints and mounts required')
        if not isinstance(actors, dict) or 'ego' not in actors:
            raise ValueError('Native camera actor map required')
        if type(timeout_s) not in (int, float) or timeout_s <= 0:
            raise ValueError('Positive original camera wait required')
        self.world, self.root = world, Path(root).resolve()
        self.blueprints, self.mounts, self.actors = blueprints, mounts, actors
        self.timeout_s, self.encoder_factory = timeout_s, encoder_factory
        self.sensors, self.queues, self.encoder = {}, {}, None

    def __enter__(self):
        try:
            for name in CAMERAS:
                mount = self.mounts[name]
                if (not isinstance(mount, dict) or set(mount) != {'transform', 'attach_to'} or
                        mount['attach_to'] not in (None, 'ego', 'other', 'officer')):
                    raise ValueError('Invalid original camera mount: ' + name)
                parent = self.actors.get(mount['attach_to'])
                if mount['attach_to'] is not None and parent is None:
                    raise ValueError('Original camera attachment actor missing: ' + name)
                options = {} if parent is None else {'attach_to': parent}
                sensor = self.world.spawn_actor(self.blueprints[name],
                                                mount['transform'], **options)
                if sensor is None:
                    raise ValueError('Original camera spawn failed: ' + name)
                self.sensors[name] = sensor
                self.queues[name] = Queue()
                sensor.listen(self.queues[name].put)
            self.encoder = self.encoder_factory(self.root)
            self.encoder.__enter__()
            return self
        except BaseException:
            self._close(abort=True)
            raise

    def readback(self, native_frame):
        if type(native_frame) is not int or self.encoder is None:
            raise ValueError('Original camera media not ready')
        snapshot = self.world.get_snapshot()
        if snapshot.frame != native_frame:
            raise ValueError('Native snapshot and camera frame differ')
        packets = {}
        for name in CAMERAS:
            try:
                packet = self.queues[name].get(timeout=self.timeout_s)
            except Empty as exc:
                raise ValueError('Original camera packet missing: ' + name) from exc
            if (packet.frame != native_frame or
                    abs(packet.timestamp - snapshot.timestamp.elapsed_seconds) > 1e-3):
                raise ValueError('Original camera frame or time differs: ' + name)
            packets[name] = packet
        self.encoder.validate_packets(packets)
        index = self.encoder.count
        self.encoder.add_packets(packets)
        return {name: {'carla_frame': native_frame,
                       'raw_source': str(self.root / (name + '.mkv')) +
                       '#frame-' + str(index),
                       'video_frame': index, 'width': packets[name].width,
                       'height': packets[name].height}
                for name in CAMERAS}

    def _close(self, abort):
        failure = None
        for sensor in reversed(list(self.sensors.values())):
            try:
                sensor.stop()
                sensor.destroy()
            except BaseException as exc:
                failure = failure or exc
        self.sensors = {}
        if self.encoder is not None and self.encoder.processes:
            try:
                self.encoder._finish(abort=abort or failure is not None)
            except BaseException as exc:
                failure = failure or exc
        if failure is not None:
            raise failure

    def __exit__(self, kind, value, trace):
        self._close(abort=kind is not None)
        return False

"""Per-frame officer direction program for the exact exception comparisons.

The caller supplies a Native bone-pose adapter reviewed for the selected walker.
The adapter must move the visible arm bones and report the realized pose. A
programmed direction is never substituted for an original-camera observation.
"""

from dataclasses import dataclass
import math


SUFFIXES = (
    "officer_controls_go",
    "officer_controls_hold",
    "officer_present_inactive",
    "stop_line_reference",
    "crosswalk_reference",
    "nearest_view_reference",
)
REFERENCE_SUFFIXES = ("stop_line_reference", "crosswalk_reference",
                      "nearest_view_reference")
PREFIX = "testing__C158196__NRS-484B-257-2__motor_vehicle_driver__"



def behavior_suffix(case_id):
    if isinstance(case_id, str) and case_id.startswith(PREFIX):
        suffix = case_id[len(PREFIX):]
        if suffix in SUFFIXES:
            return suffix
    raise ValueError("Unknown exact subsection 2 officer case")


@dataclass(frozen=True)
class DirectionPhase:
    start_frame: int
    end_frame: int
    direction: str


def phases(case_id: str, frames: int = 600, go_frame: int | None = None) -> tuple[DirectionPhase, ...]:
    if type(frames) is not int or frames < 3:
        raise ValueError("Officer program needs a complete 20 Hz capture")
    suffix = behavior_suffix(case_id)
    if suffix == "officer_controls_go":
        switch = frames // 2 if go_frame is None else go_frame
        if type(switch) is not int or not 0 < switch < frames:
            raise ValueError("Officer go frame outside capture")
        return (DirectionPhase(0, switch, "stop"),
                DirectionPhase(switch, frames, "go"))
    if suffix == "officer_controls_hold":
        return (DirectionPhase(0, frames, "stop"),)
    return (DirectionPhase(0, frames, "none"),)


def apply_direction(actor, adapter, case_id: str, frame_index: int,
                    frames: int = 600, go_frame: int | None = None) -> dict:
    """Apply an explicit visible-bone pose and retain its Native readback.

    ``adapter`` takes (actor, direction) and returns a source-shaped readback
    with the same actor ID, pose name and at least one realized bone transform.
    It must raise when the selected walker lacks the necessary Native API.
    """
    if type(frame_index) is not int or not 0 <= frame_index < frames:
        raise ValueError("Officer direction frame outside capture")
    direction = next(p.direction for p in phases(case_id, frames, go_frame)
                     if p.start_frame <= frame_index < p.end_frame)
    if direction == "none":
        if actor is not None and type(getattr(actor, "id", None)) is not int:
            raise ValueError("Native officer identity missing")
        if case_id.endswith("__officer_present_inactive") and actor is None:
            raise ValueError("Inactive-officer comparison lacks the officer actor")
        return {"frame_index": frame_index, "officer_actor_id": getattr(actor, "id", None),
                "programmed_direction": "none", "pose_applied": False}
    if actor is None or type(getattr(actor, "id", None)) is not int:
        raise ValueError("Native officer identity missing")
    if adapter is None:
        raise ValueError("Native visible-bone direction adapter missing")
    readback = adapter(actor, direction)
    if (not isinstance(readback, dict) or
            readback.get("officer_actor_id") != actor.id or
            readback.get("direction") != direction or
            not isinstance(readback.get("realized_bones"), dict) or
            not readback["realized_bones"]):
        raise ValueError("Native officer direction pose readback missing")
    return {"frame_index": frame_index, "officer_actor_id": actor.id,
            "programmed_direction": direction, "pose_applied": True,
            "realized_bones": readback["realized_bones"]}


def native_bone_adapter(carla, stop_pose: dict, go_pose: dict):
    """Create the Native walker adapter from reviewed, named arm rotations.

    Pose maps use walker bone names as keys and pitch/yaw/roll degrees as values.
    The selected walker must expose those bones; unsupported walkers fail before
    capture is sealed. Bone readback proves API application, not visible pixels.
    """
    poses = {"stop": stop_pose, "go": go_pose}
    if not all(isinstance(p, dict) and p for p in poses.values()):
        raise ValueError("Both visible-direction bone poses are required")
    for pose in poses.values():
        for name, angles in pose.items():
            if (not isinstance(name, str) or not name or not isinstance(angles, dict) or
                    set(angles) != {"pitch", "yaw", "roll"}):
                raise ValueError("Named officer arm bone rotation required")
            if any(type(value) not in (int, float) or not math.isfinite(value)
                   for value in angles.values()):
                raise ValueError("Officer bone rotation must be finite")

    def bone_parts(entry):
        if hasattr(entry, "name") and hasattr(entry, "relative"):
            return entry.name, entry.relative
        if isinstance(entry, (tuple, list)) and len(entry) >= 3:
            return entry[0], entry[2]
        raise ValueError("Unsupported Native walker bone readback shape")

    def apply(actor, direction):
        if direction not in poses:
            raise ValueError("Unsupported officer direction")
        original = actor.get_bones()
        available = {bone_parts(entry)[0] for entry in original.bone_transforms}
        missing = set(poses[direction]) - available
        if missing:
            raise ValueError("Selected walker lacks officer arm bones: " + ", ".join(sorted(missing)))
        updates = [(name, carla.Transform(rotation=carla.Rotation(**angles)))
                   for name, angles in poses[direction].items()]
        actor.set_bones(carla.WalkerBoneControl(updates))
        actor.blend_pose(1.0)
        readback = {name: relative.rotation
                    for entry in actor.get_bones().bone_transforms
                    for name, relative in [bone_parts(entry)]
                    if name in poses[direction]}
        if set(readback) != set(poses[direction]):
            raise ValueError("Native officer arm-bone readback incomplete")
        realized = {name: {axis: float(getattr(rotation, axis))
                           for axis in ("pitch", "yaw", "roll")}
                    for name, rotation in readback.items()}
        for name, target in poses[direction].items():
            if any(not math.isfinite(realized[name][axis]) or
                   abs(realized[name][axis] - target[axis]) > 2.0
                   for axis in ("pitch", "yaw", "roll")):
                raise ValueError("Native officer arm-bone pose differs from command")
        return {"officer_actor_id": actor.id, "direction": direction,
                "realized_bones": realized}

    return apply

"""Engineering controller for the subsection 1 stopping-reference order.

The reference comes from sourced site geometry. A commanded brake never proves
that a Native vehicle stopped in the required place; original body and velocity
samples must confirm it. No numeric speed or distance is a legal threshold.
"""

from dataclasses import dataclass
import math
from pathlib import Path
import xml.etree.ElementTree as ET


def _finite(value, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError('Missing finite ' + label)
    return float(value)


def _xml_float(value, label):
    try:
        return _finite(float(value), label)
    except (TypeError, ValueError) as error:
        raise ValueError('Missing finite ' + label) from error


def select_reference(site):
    """Select line, else near crosswalk, else nearest-view point from source."""
    if not isinstance(site, dict):
        raise ValueError('Missing sourced stopping-reference geometry')
    boundary = _finite(site.get('ego_intersection_boundary_x_m'), 'intersection boundary')
    for kind in ('stop_line', 'near_crosswalk', 'nearest_view'):
        item = site.get(kind)
        if not isinstance(item, dict) or type(item.get('present')) is not bool:
            raise ValueError('Missing sourced ' + kind + ' presence')
        if item['present']:
            x = _finite(item.get('x_m'), kind + ' position')
            source = item.get('source')
            if not isinstance(source, str) or not source:
                raise ValueError('Unsourced ' + kind + ' position')
            if x >= boundary:
                raise ValueError('Stopping reference is within intersection')
            return {'kind': kind, 'x_m': x, 'source': source,
                    'intersection_boundary_x_m': boundary,
                    'legal_visibility_review_pending': kind == 'nearest_view'}
    raise ValueError('No sourced stopping reference')


def from_authored_site(path):
    """Read marked line/crosswalk and an explicit unverified view candidate."""
    path = Path(path)
    root = ET.parse(path).getroot()
    if root.tag != 'OpenDRIVE':
        raise ValueError('Stopping-reference source is not OpenDRIVE')
    road = root.find("./road[@id='158190']")
    if road is None:
        raise ValueError('Signed ego approach is absent')
    start = road.find('./planView/geometry')
    if start is None or start.find('line') is None or _xml_float(start.get('hdg'), 'road heading') != 0:
        raise ValueError('Signed approach is not the authored straight eastbound road')
    origin = _xml_float(start.get('x'), 'road origin')
    boundary = origin + _xml_float(road.get('length'), 'ego road length')
    objects = road.findall('./objects/object')
    line = [item for item in objects if item.get('type') == 'roadMark'
            and item.get('name') == 'StopLine']
    walk = [item for item in objects if item.get('type') == 'crosswalk']
    if len(line) > 1 or len(walk) > 1:
        raise ValueError('Ambiguous authored stopping reference')
    view = [item for item in road.findall('userData')
            if item.get('code') == 'nearestViewCandidateX']
    if len(view) != 1:
        raise ValueError('Missing authored nearest-view candidate')
    line_x = origin + _xml_float(line[0].get('s'), 'stop line s') if line else None
    walk_x = (origin + _xml_float(walk[0].get('s'), 'crosswalk s')
              - _xml_float(walk[0].get('width'), 'crosswalk width') / 2) if walk else None
    candidate = _xml_float(view[0].get('value'), 'nearest-view candidate')
    geometry = {'ego_intersection_boundary_x_m': boundary,
                'stop_line': {'present': bool(line), 'x_m': line_x,
                              'source': path.name + '#' + line[0].get('id') if line else None},
                'near_crosswalk': {'present': bool(walk), 'x_m': walk_x,
                                   'source': path.name + '#' + walk[0].get('id') if walk else None},
                'nearest_view': {'present': True, 'x_m': candidate,
                                 'source': path.name + '#nearestViewCandidateX'}}
    return select_reference(geometry)


@dataclass
class ApproachState:
    phase: str = 'approach'
    stopped_ticks: int = 0
    overshot_reference: bool = False


def control_step(state, *, front_x_m, speed_mps, reference, hold_ticks,
                 throttle=0.3, deceleration_mps2=3.0, margin_m=1.0):
    """Return a bounded command; flag overshoot instead of claiming success.

    `front_x_m` is the most forward original ego body x coordinate, and x grows
    toward the junction. `deceleration_mps2` and `margin_m` are engineering
    margins. Native deceleration and stop placement remain observed outcomes.
    """
    if not isinstance(state, ApproachState) or state.phase not in {
            'approach', 'braking', 'holding', 'proceed', 'overshot'}:
        raise ValueError('Invalid approach controller state')
    front = _finite(front_x_m, 'ego front x')
    speed = _finite(speed_mps, 'ego speed')
    if speed < 0:
        raise ValueError('Negative ego speed')
    target = _finite(reference.get('x_m') if isinstance(reference, dict) else None,
                     'selected stopping reference')
    if type(hold_ticks) is not int or hold_ticks < 1:
        raise ValueError('Positive engineering hold ticks required')
    if not 0 < _finite(throttle, 'throttle') <= 1:
        raise ValueError('Invalid throttle')
    if _finite(deceleration_mps2, 'deceleration') <= 0 or _finite(margin_m, 'margin') < 0:
        raise ValueError('Invalid braking engineering values')
    if state.phase not in {'proceed', 'overshot'} and front > target:
        state.phase, state.overshot_reference = 'overshot', True
    if state.phase == 'overshot':
        return {'throttle': 0.0, 'brake': 1.0, 'phase': 'overshot',
                'engineering_hold_reached': False}
    if state.phase == 'proceed':
        return {'throttle': float(throttle), 'brake': 0.0, 'phase': 'proceed',
                'engineering_hold_reached': True}
    braking_distance = speed * speed / (2 * deceleration_mps2) + margin_m
    if state.phase == 'approach' and target - front <= braking_distance:
        state.phase = 'braking'
    if state.phase == 'approach':
        return {'throttle': float(throttle), 'brake': 0.0, 'phase': 'approach',
                'engineering_hold_reached': False}
    if speed > 0.05:
        return {'throttle': 0.0, 'brake': 1.0, 'phase': 'braking',
                'engineering_hold_reached': False}
    state.phase = 'holding'
    state.stopped_ticks += 1
    if state.stopped_ticks < hold_ticks:
        return {'throttle': 0.0, 'brake': 1.0, 'phase': 'holding',
                'engineering_hold_reached': False}
    state.phase = 'proceed'
    return {'throttle': float(throttle), 'brake': 0.0, 'phase': 'proceed',
            'engineering_hold_reached': True}

"""Four synchronized original-camera encoders for C158196 subsection 2."""

from pathlib import Path
import subprocess

CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
CAMERA_SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
                "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


class FourCameraEncoder:
    """Retain four original BGRA sensor streams in lossless FFV1 containers."""

    def __init__(self, root, sizes=None, fps=20):
        self.root = Path(root)
        self.sizes = dict(CAMERA_SIZES if sizes is None else sizes)
        if set(self.sizes) != set(CAMERAS) or type(fps) is not int or fps <= 0:
            raise ValueError("Four named camera dimensions and integer rate required")
        if any(not isinstance(size, (tuple, list)) or len(size) != 2 or
               any(type(v) is not int or v <= 0 for v in size)
               for size in self.sizes.values()):
            raise ValueError("Invalid camera dimensions")
        self.fps = fps
        self.processes = {}
        self.count = 0

    def __enter__(self):
        self.root.mkdir(parents=True, exist_ok=True)
        if any((self.root / (name + ".mkv")).exists() for name in CAMERAS):
            raise ValueError("Original camera video already exists")
        try:
            for name in CAMERAS:
                width, height = self.sizes[name]
                command = ["ffmpeg", "-hide_banner", "-loglevel", "error", "-y",
                           "-f", "rawvideo", "-pixel_format", "bgra", "-video_size",
                           f"{width}x{height}", "-framerate", str(self.fps),
                           "-i", "pipe:0", "-an", "-c:v", "ffv1", "-level", "3",
                           "-pix_fmt", "bgr0", str(self.root / (name + ".mkv"))]
                self.processes[name] = subprocess.Popen(command, stdin=subprocess.PIPE,
                                                        stdout=subprocess.DEVNULL,
                                                        stderr=subprocess.PIPE)
        except Exception:
            self._finish(abort=True)
            raise
        return self

    def validate_packets(self, packets):
        if set(packets) != set(CAMERAS):
            raise ValueError("Four original camera packets required")
        for name in CAMERAS:
            packet = packets[name]
            width, height = self.sizes[name]
            if (packet.width, packet.height) != (width, height) or len(packet.raw_data) != width * height * 4:
                raise ValueError("Camera pixels differ from capture profile: " + name)

    def add_packets(self, packets):
        self.validate_packets(packets)
        for name in CAMERAS:
            self.processes[name].stdin.write(packets[name].raw_data)
        self.count += 1

    def _finish(self, abort=False):
        failures = []
        self.exit_codes = {}
        processes, self.processes = self.processes, {}
        for name, process in processes.items():
            if abort:
                if process.poll() is None:
                    process.kill()
            process.stdin.close()
            stderr = process.stderr.read().decode("utf-8", errors="replace")
            process.stderr.close()
            code = process.wait()
            self.exit_codes[name] = code
            if not abort and (code != 0 or not (self.root / (name + ".mkv")).is_file()):
                failures.append(name + ": " + stderr[-400:])
        if failures:
            raise ValueError("Four-camera FFV1 encoding failed: " + "; ".join(failures))

    def __exit__(self, kind, value, trace):
        self._finish(abort=kind is not None)
        return False

